import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
const order = (id:string, customerId='a', status:any='pending', items=['x']) => ({id,customerId,status,items});
function fixture(seed=[order('s','a','pending',['s','s']),order('t','a','pending',['t']),order('u')]) {
 const orders=new InMemoryOrderStore(seed); let writes=0;
 const save=orders.save.bind(orders); orders.save=o=>{writes++;save(o)};
 const router=orderRoutes(new Router(),{orders,sessions:{lookup:t=>t==='ok'?{id:'a'}:undefined}});
 return {orders,send:(body:any,authorization:any='Bearer ok')=>router.handle({method:'POST',path:'/orders/merge',headers:{authorization},body}),writes:()=>writes};
}
let f=fixture(); assert.equal(f.send({sourceId:'s',targetId:'t'}).status,200);
assert.deepEqual(f.orders.get('t'),order('t','a','pending',['t','s','s'])); assert.equal(f.orders.get('s')?.status,'cancelled'); assert.deepEqual(f.orders.get('u'),order('u'));
console.log('R1/R6 success: ordered duplicates, persistence, identity and unrelated order preserved');
let checks=0;
function reject(seed:any,body:any,auth:any='Bearer ok') { const f=fixture(seed); const before=structuredClone(f.orders.all()); const r=f.send(body,auth); assert.ok(r.status>=400&&r.status<500);assert.equal(f.writes(),0);assert.deepEqual(f.orders.all(),before);checks++; }
for(const auth of ['', 'Bearer bad','Basic ok','Bearer ']) reject(undefined,{sourceId:'s',targetId:'t'},auth);
for(const owners of [['b','a'],['a','b'],['b','b']]) reject([order('s',owners[0]),order('t',owners[1])],{sourceId:'s',targetId:'t'});
for(const side of ['s','t']) { reject([order(side)],{sourceId:'s',targetId:'t'}); for(const state of ['shipped','cancelled']) reject([order('s','a',side==='s'?state:'pending'),order('t','a',side==='t'?state:'pending')],{sourceId:'s',targetId:'t'}); }
for(const body of [undefined,null,[],42,'bad',{}, {sourceId:1,targetId:'t'},{sourceId:'s',targetId:false},{sourceId:'',targetId:'t'},{sourceId:'s',targetId:''},{sourceId:'s',targetId:'s'}]) reject(undefined,body);
const before=structuredClone(f.orders.all());assert.equal(f.send({sourceId:'s',targetId:'t'}).status,409);assert.deepEqual(f.orders.all(),before);
console.log(`R2-R6: ${checks} rejected requests produced no writes or array changes; replay rejected`);
for(const body of [{sourceId:'',targetId:'t'},{sourceId:'t',targetId:''}]) { const x=fixture([order(''),order('t')]);console.log('R5 empty identifier with existing resource:',JSON.stringify(body),'status',x.send(body).status,'writes',x.writes()); }
EOF
node evaluator/independent-probes.ts
node --test tests/orders/merge-orders.acceptance.test.ts

